//! Ship blueprints: vertices, edges, faces and stats for every ship in the disc version.
//! The data is generated by `scripts/extract_ships.py` from the annotated disassembly.

#![no_std]

pub mod blueprints;

pub use blueprints::*;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Vertex {
    pub x: i16,
    pub y: i16,
    pub z: i16,
    /// Up to four faces this vertex belongs to (used for visibility).
    pub faces: [u8; 4],
    /// Distance visibility threshold, 0..=31.
    pub vis: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Edge {
    pub v1: u8,
    pub v2: u8,
    pub faces: [u8; 2],
    pub vis: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Face {
    pub nx: i16,
    pub ny: i16,
    pub nz: i16,
    pub vis: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Blueprint {
    pub name: &'static str,
    /// Max cargo canisters released on destruction.
    pub canisters: u8,
    /// Market item index + 1 awarded when scooped (0 = not scoopable).
    pub scoop: u8,
    /// Square root of the targetable area.
    pub area: u16,
    pub max_edges: u8,
    /// Index of the vertex lasers fire from.
    pub gun_vertex: u8,
    pub explosion: u8,
    /// Bounty in tenths of a credit.
    pub bounty: u16,
    /// Distance (in high-byte units) beyond which the ship is a dot.
    pub vis: u8,
    pub energy: u8,
    pub speed: u8,
    /// Face normals are scaled by 2^scale.
    pub scale: u8,
    pub laser: u8,
    pub missiles: u8,
    pub vertices: &'static [Vertex],
    pub edges: &'static [Edge],
    pub faces: &'static [Face],
}

impl Blueprint {
    /// Rough bounding radius in ship units, for collision and dot rendering.
    pub fn radius(&self) -> i32 {
        self.vertices
            .iter()
            .map(|v| {
                (v.x as i32)
                    .abs()
                    .max((v.y as i32).abs())
                    .max((v.z as i32).abs())
            })
            .max()
            .unwrap_or(0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn documented_counts() {
        assert_eq!(
            (
                CORIOLIS.vertices.len(),
                CORIOLIS.edges.len(),
                CORIOLIS.faces.len()
            ),
            (16, 28, 14)
        );
        assert_eq!(
            (
                COBRA_MK_3.vertices.len(),
                COBRA_MK_3.edges.len(),
                COBRA_MK_3.faces.len()
            ),
            (28, 38, 13)
        );
        assert_eq!(COBRA_MK_3.energy, 150);
        assert_eq!(COBRA_MK_3.speed, 28);
        assert_eq!(MISSILE.vertices.len(), 17);
    }

    #[test]
    fn every_index_in_range() {
        for b in ALL {
            for e in b.edges {
                assert!((e.v1 as usize) < b.vertices.len(), "{} edge v1", b.name);
                assert!((e.v2 as usize) < b.vertices.len(), "{} edge v2", b.name);
                for f in e.faces {
                    // 15 marks an edge or vertex that is always drawn.
                    assert!(
                        (f as usize) < b.faces.len().max(1) || f == 15,
                        "{} edge face {f}",
                        b.name
                    );
                }
            }
            for v in b.vertices {
                for f in v.faces {
                    assert!(
                        (f as usize) < b.faces.len().max(1) || f == 15,
                        "{} vertex face {f}",
                        b.name
                    );
                }
            }
            assert!(
                (b.gun_vertex as usize) < b.vertices.len(),
                "{} gun vertex",
                b.name
            );
        }
    }
}
